let datain = msg.payload;

// แปลง body จาก string -> object
let body = typeof datain.body === "string"
    ? JSON.parse(datain.body || "{}")
    : (datain.body || {});

function pick(...values) {
    for (const value of values) {
        if (value !== undefined && value !== null && String(value).trim() !== "") {
            return String(value);
        }
    }
    return "-";
}

function formatDate(dateStr) {
    if (!dateStr || dateStr === "-") return "-";

    const parts = String(dateStr).split("-");
    if (parts.length !== 3) return dateStr;

    const [year, month, day] = parts;
    return `${day}-${month}-${year.slice(-2)}`;
}

let samplePreparationText = body.sample_preparation || "";
samplePreparationText = samplePreparationText
    .replace(/₀/g, "0")
    .replace(/₁/g, "1")
    .replace(/₂/g, "2")
    .replace(/₃/g, "3")
    .replace(/₄/g, "4")
    .replace(/₅/g, "5")
    .replace(/₆/g, "6")
    .replace(/₇/g, "7")
    .replace(/₈/g, "8")
    .replace(/₉/g, "9")
    .replace(/≤/g, "<=")
    .replace(/≥/g, ">=")
    .replace(/°/g, "o")
    .replace(/˚/g, "o")
    .replace(/µ/g, "u")
    .replace(/α/g, "a");

let sampleCode = pick(body.SampleCode, body.sample_code, datain.reqNo);
let samplingDate = formatDate(pick(body.SamplingDate, body.sampling_date));
// Type ('Special' / 'Service lab') พิมพ์ต่อใต้ Sampling date
let requestType = pick(body.Type, body.type);
let furnance = pick(body.Furnance, body.furnance);
let sampleName = pick(body.SampleName, body.lot_no);
let customerName = pick(body.CustFull, body.sample_name);

let output = [];

output.push({
    payload: `
^XA
^CF0,20
^FO0,0^GB400,550,3^FS

^FO70,190^BQN,2,6,M^FDMM, ${sampleCode}^FS

^FO225,30^A0R,20,20^FDSampling date:^FS
^FO225,220^A0R,20,20^FD${samplingDate}^FS

^FO255,30^A0R,20,20^FDType:^FS
^FO255,220^A0R,20,20^FD${requestType}^FS

^FO285,30^A0R,20,20^FDFurnance:^FS
^FO285,220^A0R,20,20^FD${furnance}^FS

^FO315,30^A0R,20,20^FDSample name:^FS
^FO315,220^A0R,20,20^FD${sampleName}^FS

^FO345,30^A0R,20,20^FDCustomer name:^FS
^FO345,220^A0R,20,20^FD${customerName}^FS

^FO375,30^A0R,20,20^FDCode:^FS
^FO375,220^A0R,20,20^FD${sampleCode}^FS

^XZ
`
});

let printer = datain.printer;

if (printer === "BPMKT") {
    return [output, null, null, null];
} else if (printer === "BPTTC") {
    return [null, output, null, null];
} else if (printer === "RYMKT") {
    return [null, null, output, null];
} else if (printer === "RYTTC") {
    return [null, null, null, output];
}

return [null, null, null, null];
